/**
 * The app's OWN words (headings, labels, chips, buttons, status and help lines) in every app language. Pure, no AI.
 *
 * Why this exists: a teammate who reads Vietnamese tried the site in Vietnamese and found "the headings stay in
 * english". The AI's explanations already came back in the chosen language; the interface around them did not.
 *
 * Rules kept here so the components cannot drift from them:
 *
 * - The paper's own words are never translated. Quotes stay exactly as written (the product's paper-first rule).
 *   Only the labels AROUND them are translated.
 * - "Copied word for word from your paper" keeps the meaning "these are the paper's exact words". "Not double-checked
 *   yet" keeps the meaning "not verified". A warning label never gets softer than the English.
 * - Text meant for an English-speaking pharmacist, front desk or caller (askPerson questions, call scripts) stays in
 *   English on purpose; the label around it says why.
 * - Register: the polite form a clinic uses with a patient or family in each language (see UI_REGISTER). Short
 *   sentences, common words, but polite.
 * - Every non-English entry is a MACHINE DRAFT. See UI_REVIEWED. Nothing here claims native review.
 *
 * Proper names stay as they are in every language: ATLAS, Pip, 211, 911, ZIP codes, phone numbers.
 */

import type { LANGUAGES } from "./schema";

export type Lang = (typeof LANGUAGES)[number];

/** Review status of the translations. Machine drafts until a native speaker checks them. */
export const UI_REVIEWED: Record<Lang, string | false> = {
  English: "source",
  Spanish: false,
  // A teammate who reads Vietnamese tried the live site (2026-10-04) and said the meaning is clear and the formal tone
  // is right for patients. Not a line-by-line review of this table.
  Vietnamese: "partial, teammate (tone and general meaning only)",
  Korean: false,
  Chinese: false,
  Amharic: false,
  French: false,
};

/**
 * The register each language uses, matching the existing translated strings (pip.ts, helperLink.ts, call/ncco.ts) and
 * the Vietnamese reviewer's note that a formal, respectful tone is the default when speaking to patients.
 */
export const UI_REGISTER: Record<Lang, string> = {
  English: "plain everyday words, second person",
  Spanish: "usted (Empiece, Revise, su hoja)",
  Vietnamese: "formal and respectful: quý vị for 'you', as a clinic addresses patients",
  Korean: "polite 합니다/해요 style (하세요, 확인하세요)",
  Chinese: "您 where a pronoun is needed; simplified characters",
  Amharic: "polite second person (-ዎ / -ዎት forms: ሰነድዎ, ይደውሉ)",
  French: "vous (Vérifiez, votre document)",
};

/** HTML lang codes, so screen readers use the right voice for the app's own words. */
export const UI_LANG_CODE: Record<Lang, string> = {
  English: "en", Spanish: "es", Vietnamese: "vi", Korean: "ko", Chinese: "zh-Hans", Amharic: "am", French: "fr",
};

/** Each language's own name, for the language picker (the value stays the English name the API expects). */
export const LANGUAGE_NAME: Record<Lang, string> = {
  English: "English", Spanish: "Español", Vietnamese: "Tiếng Việt", Korean: "한국어", Chinese: "中文", Amharic: "አማርኛ", French: "Français",
};

type Row = Record<Lang, string>;

