  "kind.medication": { English: "Medicine", Spanish: "Medicina", Vietnamese: "Thuốc", Korean: "약", Chinese: "药物", Amharic: "መድኃኒት", French: "Médicament" },
  "kind.lab_test": { English: "Lab test", Spanish: "Análisis", Vietnamese: "Xét nghiệm", Korean: "검사", Chinese: "化验", Amharic: "የላብራቶሪ ምርመራ", French: "Analyse" },
  "kind.referral": { English: "Referral", Spanish: "Referido", Vietnamese: "Giấy giới thiệu", Korean: "의뢰", Chinese: "转诊", Amharic: "ሪፈራል", French: "Orientation" },
  "kind.follow_up_visit": { English: "Next visit", Spanish: "Próxima cita", Vietnamese: "Lần khám tới", Korean: "다음 진료", Chinese: "下次就诊", Amharic: "ቀጣይ ጉብኝት", French: "Prochaine visite" },
  "kind.self_care": { English: "Daily care", Spanish: "Cuidado diario", Vietnamese: "Chăm sóc hằng ngày", Korean: "매일 관리", Chinese: "日常护理", Amharic: "የዕለት እንክብካቤ", French: "Soins au quotidien" },
