  "plan.yourPlanN": { English: "Your plan, {steps}", Spanish: "Su plan, {steps}", Vietnamese: "Kế hoạch của quý vị, {steps}", Korean: "내 계획, {steps}", Chinese: "您的计划，{steps}", Amharic: "ዕቅድዎ፣ {steps}", French: "Votre plan, {steps}" },
  "plan.tapOne": { English: "Tap one for the full plan. Tick it off when it's done.", Spanish: "Toque uno para ver el plan completo. Márquelo cuando esté hecho.", Vietnamese: "Chạm vào một bước để xem đầy đủ. Đánh dấu khi đã xong.", Korean: "하나를 누르면 전체 계획이 보입니다. 다 하면 체크하세요.", Chinese: "点一项看完整计划。完成后打勾。", Amharic: "ሙሉ ዕቅዱን ለማየት አንዱን ይንኩ። ሲጨርሱ ምልክት ያድርጉ።", French: "Touchez-en une pour le plan complet. Cochez-la quand c'est fait." },
