  "plan.whyThis": { English: "Why this?", Spanish: "¿Por qué esto?", Vietnamese: "Tại sao chọn cái này?", Korean: "왜 이것인가요?", Chinese: "为什么是这个？", Amharic: "ለምን ይህ?", French: "Pourquoi ceci ?" },
