  "saved.deleteAsk": { English: "Delete {name}?", Spanish: "¿Borrar {name}?", Vietnamese: "Xóa {name}?", Korean: "{name}을(를) 지울까요?", Chinese: "删除 {name}？", Amharic: "{name}ን ያጥፉ?", French: "Supprimer {name} ?" },
  "saved.deleteConfirm": { English: "Delete {name} from this device? This can't be undone.", Spanish: "¿Borrar {name} de este dispositivo? No se puede deshacer.", Vietnamese: "Xóa {name} khỏi thiết bị này? Không thể hoàn tác.", Korean: "{name}을(를) 이 기기에서 지울까요? 되돌릴 수 없습니다.", Chinese: "从这台设备上删除 {name}？删除后无法恢复。", Amharic: "{name}ን ከዚህ መሣሪያ ያጥፉ? ይህ ሊመለስ አይችልም።", French: "Supprimer {name} de cet appareil ? C'est définitif." },
