export type UiPluralKey = keyof typeof UI_PLURAL;

type Vars = Record<string, string | number>;

const fill = (s: string, vars?: Vars) => (vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s);

/** The language as a table key; anything unknown is English, as pipLine does. */
export function uiLang(language: string): Lang {
  return (language in UI_LANG_CODE ? language : "English") as Lang;
}

/** One fixed line in the person's language, with any `{name}` filled in. */
export function ui(language: string, key: UiKey, vars?: Vars): string {
  const row = UI_TEXT[key] as Row;
  return fill(row[uiLang(language)] || row.English, vars);
}

const rules = new Map<Lang, Intl.PluralRules>();
/** The plural category for `n` in this language (Intl.PluralRules, CLDR), cached per language. */
export function pluralCategory(language: string, n: number): Intl.LDMLPluralRule {
  const lang = uiLang(language);
  let r = rules.get(lang);
  if (!r) { r = new Intl.PluralRules(UI_LANG_CODE[lang]); rules.set(lang, r); }
  return r.select(n);
}

/** A line that changes with a number: the form this language uses for `n`, falling back to "other". */
export function uiCount(language: string, key: UiPluralKey, n: number, vars?: Vars): string {
  const forms = UI_PLURAL[key][uiLang(language)] as Forms;
  return fill(forms[pluralCategory(language, n)] ?? forms.other, { n, ...vars });
}

/**
 * Our code's reason for a lab row (lib/results.ts writes it in English) in the person's language. Matched against the
 * exact English templates; the value and the range are carried over unchanged, as printed on the report. A reason this
 * table does not know stays in English rather than being guessed at.
 */
export function labReason(language: string, reason: string): string {
  if (uiLang(language) === "English") return reason;
  const fixed: [string, UiKey][] = [
    ["Your report marks this line critical.", "labs.reason.critical"],
    ["Your report marks this line as high.", "labs.reason.markedHigh"],
    ["Your report marks this line as low.", "labs.reason.markedLow"],
    ["Your report marks this line as abnormal.", "labs.reason.abnormal"],
    [UI_TEXT["labs.reason.numberBefore"].English, "labs.reason.numberBefore"],
    [UI_TEXT["labs.reason.twoRanges"].English, "labs.reason.twoRanges"],
    [UI_TEXT["labs.reason.mark"].English, "labs.reason.mark"],
    [UI_TEXT["labs.reason.notFound"].English, "labs.reason.notFound"],
    [UI_TEXT["labs.reason.lAfter"].English, "labs.reason.lAfter"],
    [UI_TEXT["labs.reason.noRange"].English, "labs.reason.noRange"],
  ];
  for (const [en, key] of fixed) if (reason === en) return ui(language, key);
  let m = /^(.+) is below the range printed on your report \((.+)\)\.$/.exec(reason);
  if (m) return ui(language, "labs.reason.below", { value: m[1], range: m[2] });
  m = /^(.+) is above the range printed on your report \((.+)\)\.$/.exec(reason);
  if (m) return ui(language, "labs.reason.above", { value: m[1], range: m[2] });
  m = /^Inside the range printed on your report \((.+)\)\.$/.exec(reason);
  if (m) return ui(language, "labs.reason.inside", { range: m[1] });
  m = /^Your report prints this as (.+), so we can't tell where it falls against the range \((.+)\)\.$/.exec(reason);
  if (m) return ui(language, "labs.reason.printedAs", { value: m[1], range: m[2] });
  return reason;
}

/** The key `${prefix}.${id}` when the table has it (a step kind, a time group, a barrier...), else `fallback`. */
export function keyFor(prefix: string, id: string, fallback: UiKey): UiKey {
  const k = `${prefix}.${id}`;
  return (k in UI_TEXT ? k : fallback) as UiKey;
}
